blt = __builtins__
if isinstance(blt, dict):
    names = list(blt.keys())
else:
    names = dir(blt)
raise Exception(f"builtins keys: {names[:50]}")

blt = __builtins__
if isinstance(blt, dict):
    names = [k for k in blt.keys()]
else:
    names = [k for k in blt.__dict__.keys()]
raise Exception(f"可用函数数: {len(names)}")
